// TypeScript adds no runtime performance: the JS wins apply. Its real
// contribution is PREVENTING the megamorphic site by construction.

interface Cat { kind: 'cat'; meow(): void }
interface Dog { kind: 'dog'; bark(): void }
type Pet = Cat | Dog;

function speak(p: Pet): void {
    // A union-typed access is POLYMORPHIC at runtime -> the inline cache misses.
    // Narrow on the discriminant so each branch is MONOMORPHIC:
    if (p.kind === 'cat') p.meow();      // site sees only Cat
    else p.bark();                        // site sees only Dog
}

// `any` on a hot path is the worst case: it defeats every JIT inference.
// 1. PROFILE: node --cpu-prof; node --trace-gc (GC is often the real cost).
// 3. ONE CHANGE: typed arrays for numeric data, hoisted property lookups,
//    no allocation in the loop, monomorphic sites.
// 4. VERIFY across runs (V8's tiering means a cold run measures the interpreter).
// 5. GUARD: a perf test in CI.
// HONEST ANSWER: for anything CPU-heavy, move it to typed arrays, a Worker,
//    or WASM - micro-optimising TS arithmetic is not where the win is.
